var FOOTER = "<span class=\"lda-footer-links\"><a href=\"https://www.learningdesignalliance.org\">Learning Design Alliance</a> · <a href=\"https://reports.learningdesignalliance.org\">Research reports</a> · <a href=\"https://wiki.learningdesignalliance.org\">Wiki</a> · <a href=\"https://lazuli.design\">Lazuli</a></span> &copy; Learning Design Alliance — content licensed CC BY-SA 4.0 where copyright applies; pages are written largely by AI (<a href=\"https://wiki.learningdesignalliance.org/checks/#who-wrote-this-and-the-license\">who wrote this, and the license</a>)";
try{var s=new URL(root||".",location).pathname,p=JSON.parse(localStorage.getItem(s+".__palette"));if(p&&p.color){for(var k of ["scheme","primary","accent"])if(p.color[k])document.body.setAttribute("data-md-color-"+k,p.color[k])}}catch(e){}
var parts = location.pathname.replace(/index\.html$/, "").split("/").filter(Boolean);
var slug = decodeURIComponent(parts[parts.length - 1] || "");
var b = new TextEncoder().encode(slug), h = 0x811c9dc5;
for (var i = 0; i < b.length; i++) { h ^= b[i]; h = Math.imul(h, 0x01000193) >>> 0; }
var url = root + folder + "/lt-shards/" + (h % n) + ".json.gz";
function inflate(buf) {
  var u = new Uint8Array(buf);
  if (u[0] !== 0x1f || u[1] !== 0x8b) return new TextDecoder().decode(u);
  return new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
}
var text = fetch(url).then(function (r) { if (!r.ok) throw new Error(r.status); return r.arrayBuffer(); })
  .then(inflate).then(JSON.parse);
